from typing import List

def move_one_ball(arr: List[int]) -> bool:
    if not arr:
        return True

    # Check if the array is already sorted
    if arr == sorted(arr):
        return True

    # Check if the array can be sorted by performing right shifts
    for i in range(len(arr)):
        if arr[i] > arr[(i + 1) % len(arr)]:
            return False

    return True
